using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Topstar.Application.SystemSettings;namespace Topstar.Web.Pages.Admin.Settings;[Authorize(Roles="Admin")]public sealed class EmailAccountDeleteModel(ISystemSettingsAdminService service):PageModel{public EmailAccountItem Item{get;private set;}=null!;public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){var x=await service.GetEmailAccountByIdAsync(id,ct);if(x is null)return NotFound();Item=x;return Page();}public async Task<IActionResult> OnPostAsync(Guid id,CancellationToken ct){var r=await service.DeleteEmailAccountAsync(id,ct);TempData[r.Success?"AdminMessageSuccess":"AdminMessageError"]=r.Message;return RedirectToPage("EmailAccounts");}}
